(function(){console.log("Pilot Bridge (Main World) loaded");window.Pilot={openTab:o=>{window.postMessage({source:"PILOT_SCRIPT",action:"openTab",payload:{url:o}},"*")},log:o=>console.log("[Pilot]",o),workflow:{next:o=>{console.log("[Pilot] Step completed, signaling..."),window.postMessage({source:"PILOT_SCRIPT",action:"workflowNext",payload:{data:o}},"*")},finish:()=>{console.log("[Pilot] Workflow finished"),window.postMessage({source:"PILOT_SCRIPT",action:"workflowFinish",payload:{}},"*")},fail:o=>{console.error("[Pilot] Workflow FAILED:",o),window.postMessage({source:"PILOT_SCRIPT",action:"workflowFail",payload:{reason:o}},"*")}}};
})()